python3.checker:
class Node:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class Checker:
    def _to_tree(self, root):
        if root is None or root == []:
            return None
        if hasattr(root, 'val'):
            return root
        if not isinstance(root, list) or not root or root[0] is None:
            return None
        tree_root = Node(root[0])
        queue = [tree_root]
        i = 1
        while queue and i < len(root):
            node = queue.pop(0)
            if i < len(root) and root[i] is not None:
                node.left = Node(root[i])
                queue.append(node.left)
            i += 1
            if i < len(root) and root[i] is not None:
                node.right = Node(root[i])
                queue.append(node.right)
            i += 1
        return tree_root

    def sumNumbers(self, root, result):
        if not isinstance(result, int):
            return False
        root = self._to_tree(root)
        def dfs(node, current):
            if node is None:
                return 0
            current = current * 10 + node.val
            if node.left is None and node.right is None:
                return current
            return dfs(node.left, current) + dfs(node.right, current)
        return result == dfs(root, 0)

